import{_ as t,H as a,f as o,i as n}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"01｜老项目改造的真实链路：从接手到交付，人到底做了什么？","description":"","frontmatter":{},"headers":[{"level":2,"title":"一个真实的场景","slug":"一个真实的场景","link":"#一个真实的场景","children":[]},{"level":2,"title":"你可能遇到过类似的场景","slug":"你可能遇到过类似的场景","link":"#你可能遇到过类似的场景","children":[]},{"level":2,"title":"面对这样的场景，人本来会怎么做","slug":"面对这样的场景-人本来会怎么做","link":"#面对这样的场景-人本来会怎么做","children":[]},{"level":2,"title":"为什么这件事对 AI 协作特别关键","slug":"为什么这件事对-ai-协作特别关键","link":"#为什么这件事对-ai-协作特别关键","children":[]},{"level":2,"title":"为什么“前六步”特别容易被跳过","slug":"为什么-前六步-特别容易被跳过","link":"#为什么-前六步-特别容易被跳过","children":[]},{"level":2,"title":"冷启动慢，飞轮转起来就快","slug":"冷启动慢-飞轮转起来就快","link":"#冷启动慢-飞轮转起来就快","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级老项目改造实战/01｜老项目改造的真实链路：从接手到交付，人到底做了什么？.md","filePath":"ClaudeCode企业级老项目改造实战/01｜老项目改造的真实链路：从接手到交付，人到底做了什么？.md","lastUpdated":1779815445000}'),r={name:"ClaudeCode企业级老项目改造实战/01｜老项目改造的真实链路：从接手到交付，人到底做了什么？.md"};function p(s,e,l,i,d,g){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_01-老项目改造的真实链路-从接手到交付-人到底做了什么" tabindex="-1">01｜老项目改造的真实链路：从接手到交付，人到底做了什么？ <a class="header-anchor" href="#_01-老项目改造的真实链路-从接手到交付-人到底做了什么" aria-label="Permalink to &quot;01｜老项目改造的真实链路：从接手到交付，人到底做了什么？&quot;">​</a></h1><p>你好，我是 Robert。</p><p>从这一讲开始我们正式进入课程。第一部分的 5 讲是方法论基础。这一部分不讲工具怎么用，不讲提示词怎么写，目的是把认知底座打好。学完这五讲，你应该获得三件东西： <strong>一个正确的 AI 协作心智、一张工具地图、一套判断力框架</strong>。接下来的课程内容，全部在这个底座上展开。</p><p>好，我们从 01 开始。这门课要回答的问题是： <strong>面对你公司里那个跑了几年的老项目，怎么用好 Claude Code 改它？</strong></p><p>要回答这个问题，我想先带你回到一个更基础的问题：AI 来之前，我们是怎么接手一个老项目的？这个问题听起来有点傻。你可能会想，接手老项目不就是读代码、跑起来、改 bug、上线嘛，有什么好讲的。但我发现很多人用 Claude Code 用得不顺，根源就在这里： <strong>他们在 AI 时代跳过了那些看似傻但其实关键的步骤，结果传递给 AI 的上下文是空的，改完之后自己也没法判断对不对</strong>。</p><p>所以这一讲我想做一件事： <strong>把 AI 来之前，人接手一个老项目的真实链路，从头到尾讲一遍</strong>。这条链路 AI 没有推翻，只是改变了每一步的分工。链路清楚了，后面我们讲 AI 怎么进来、哪些步骤变了、哪些没变，才有参照系。</p><h2 id="一个真实的场景" tabindex="-1">一个真实的场景 <a class="header-anchor" href="#一个真实的场景" aria-label="Permalink to &quot;一个真实的场景&quot;">​</a></h2><p>想象下这样一个场景：</p><blockquote><p>某天 leader 走过来，指着一个 GitLab 仓库说：“老张走之前维护的 xxx-scheduler，你接一下，下周一上线一个批处理任务。”</p><p>老张是上个季度离职的。这个项目部门里几个核心业务都靠它跑，公司早期几位资深工程师好多年前写的，后来换了几拨维护者，也没人完整梳理过技术资料。</p></blockquote><p>打开 README，几行部署命令加一张架构图，看两遍感觉像懂了又没懂。接着翻代码，Java + Spring Boot + MyBatis，每个类都很长，散落着各种注释。有的写着“2020-08 临时方案，等下个版本重构”，下个版本是哪个版本没说。翻到一段业务逻辑写着“// 不要删，某某对接方需要”，某某对接方是谁？删了会出什么事？代码没说。再往下是一段注释掉的代码：“// 2021-11 回滚原因:影响某个对接方的 PR 流程”。</p><p>去问 leader，文档没有，历史背景老张应该清楚，但他入职新公司了，估计不方便联系。一下午就这么过去了，一行代码都没写。</p><h2 id="你可能遇到过类似的场景" tabindex="-1">你可能遇到过类似的场景 <a class="header-anchor" href="#你可能遇到过类似的场景" aria-label="Permalink to &quot;你可能遇到过类似的场景&quot;">​</a></h2><p>这个故事你可能觉得熟悉。不一定是 xxx-scheduler，可能是公司里那个跑了三五年的订单系统、那个谁也说不清历史的交易中台、那个每次发版都要提前拉全部门开评审会的核心服务。 <strong>老项目最难的不是代码本身，是代码之外的那些东西</strong>。</p><p>是那些“不要删”的注释，是那些早已离职、再也问不到的前辈，是那些每次你想动它、都不敢动的隐性约定，是那些六年前的设计决策，当时可能是对的，今天看起来像炸药……</p><p>这些东西代码里没写，也不会写。因为写它们的人觉得“这都是常识”。离职时也不会留下来，因为谁也说不清。 <strong>这才是老项目改造的真实起点</strong>。</p><h2 id="面对这样的场景-人本来会怎么做" tabindex="-1">面对这样的场景，人本来会怎么做 <a class="header-anchor" href="#面对这样的场景-人本来会怎么做" aria-label="Permalink to &quot;面对这样的场景，人本来会怎么做&quot;">​</a></h2><p>假设你是那个接手项目的人，不急着写代码，而是先想办法了解它，通常会这么走。</p><p><strong>第一件事，找人聊</strong>。</p><p>把项目里看到的疑点列一个清单，去问身边还在这个项目周边工作过的同事。问产品，问隔壁组的架构师，问运维。每个人知道一点，拼起来至少能搞清楚“某某对接方”是谁、“2021-11 回滚”背后发生了什么。有些问题问不到答案，标记“未知”，先搁置。</p><p><strong>第二件事，把能找到的资料都翻一遍</strong>。</p><p>README、仓库里的 docs 目录、wiki、Confluence 里的旧设计文档、企微里的历史群聊记录、jira 里相关的 epic。不是要全部搞懂，是要把手头所有线索都扫一遍，有个整体的感觉。</p><p><strong>第三件事，clone 项目，浏览一遍代码</strong>。</p><p>不是从第一行读到最后一行，是看结构。有哪些模块？哪些是核心？哪些是工具类？哪些看起来是很久没人动过的老代码？哪些看起来是最近还在改的？脑子里画一张粗糙的地图。</p><p><strong>第四件事，搭起开发环境，把项目跑起来</strong>。</p><p>这一步出奇的难。依赖 MySQL 版本有要求、Redis 的 key 格式需要特定配置、有一个对接的内部服务需要 VPN，可能要折腾一整天。但跑起来的那一刻心里就有底了，能用 debug 模式断点、能看到真实的数据流向、能观察请求进来之后的完整链路。</p><p><strong>第五件事，用 curl 访问几个核心接口</strong>。</p><p>不是为了测业务，是为了验证项目确实跑通了、能看到输入输出、能复现问题。接口通了之后，才敢说“初步了解这个项目了”。</p><p><strong>第六件事，带着疑点深挖代码</strong>。</p><p>前面梳理时留下的那些“未知”标记，现在带着具体的问题去翻代码。某个业务分支是什么时候加的？谁在调用这段逻辑？有没有类似功能的调用链路？这时候代码读起来不一样了，每一处都带着上下文在读。</p><p><strong>第七件事，画出核心链路</strong>。</p><p>几张粗糙的手绘图。主流程从入口到出口、核心数据表之间的关系、依赖的外部服务。画完之后，整个项目才算在脑子里立起来。</p><p><strong>第八件事，开始动手改那个批处理任务</strong>。</p><p>改的时候也不是一口气改完。先小改一处、跑通、看结果、确认没有副作用，再改下一处。每一步都带着前面建立的那份地图。</p><p><strong>第九件事，改完了做验收</strong>。</p><p>curl 接口看主流程没有被破坏、跑了几个相关的业务场景、找人 review。然后才敢说“这个改造做完了”。</p><p>顺序可能微调，但这九件事一件都少不了。总结一下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/974062/7f9ayy6be1234d6ddbc938bf5e3a11dd.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/974062/7f9ayy6be1234d6ddbc938bf5e3a11dd.png" alt=""></a></p><p>这就是老项目改造的原始链路。这个链路不是谁发明的。工作几年、接过几个老项目，或多或少都会走到这里。区别只是你没把它写下来，或者没意识到它是一个可以复用的模式。</p><p>真正重要的是一个比例。 <strong>九步里，前六步都是了解项目，只有后三步是改造。70% 的时间花在理解上，30% 的时间才是动手</strong>。这个比例和很多人的直觉是反的。大部分人接手新项目，恨不得第一天就开始改代码。真正做得稳的工程师，反而在了解上花了更多时间。</p><h2 id="为什么这件事对-ai-协作特别关键" tabindex="-1">为什么这件事对 AI 协作特别关键 <a class="header-anchor" href="#为什么这件事对-ai-协作特别关键" aria-label="Permalink to &quot;为什么这件事对 AI 协作特别关键&quot;">​</a></h2><p>说到这儿，你可能已经开始嗅到一些味道。AI 没有改变这条链路， <strong>但它把每一步里人和 AI 的分工打乱了</strong>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/974062/186996603a3f3810d2c5f262c3a645b4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/974062/186996603a3f3810d2c5f262c3a645b4.png" alt=""></a></p><p>在传统的流程里，这九步全部是人在做。有些步骤慢（比如画核心链路）、有些步骤繁琐（比如梳理接口）、有些步骤需要耐心（比如读一个陌生的业务分支），但都是人的事。</p><p>Claude Code 进来以后，每一步都在被重新分配。读 README 这种事，AI 一次能给你出个漂亮的摘要。画架构图这种事，AI 可以扫完整个仓库给你出一份 Mermaid。梳理接口清单这种事，AI 比你手动翻快十倍。</p><p>但也有一些事 AI 帮不上。比如“某某对接方是谁”，代码里没写的事 AI 说不出来。比如“这段逻辑删了会出什么事”，AI 只能猜，不能承担责任。比如“最终这个改造要不要上线”，这是人的决策，不是 AI 的。</p><p><strong>所以用 Claude Code 用得好的工程师，其实就是在这条九步链路上，把人和 AI 的分工搞清楚的工程师</strong>。</p><p>他们知道哪一步让 AI 冲在前面、哪一步自己必须守住、哪一步需要和 AI 来回确认。这种分工不是 AI 天生就会的，是经过一段磨合才建立起来的。</p><p><strong>这门课要做的，就是帮你把这段磨合时间压缩到最短</strong>。开篇词里我说过，差的不是 AI，差的是用法，大部分人还没把这个体系摸出来。这门课就是把我这两年用过的提示词、走过的工作流、踩过的坑，系统讲一遍。</p><h2 id="为什么-前六步-特别容易被跳过" tabindex="-1">为什么“前六步”特别容易被跳过 <a class="header-anchor" href="#为什么-前六步-特别容易被跳过" aria-label="Permalink to &quot;为什么“前六步”特别容易被跳过&quot;">​</a></h2><p>我接触过不少在老项目上用 Claude Code 用得不顺的工程师，共同的问题是同一个。</p><p><strong>他们跳过了前六步</strong>。</p><p>具体表现是这样。项目刚拿到手，他们第一件事就是打开 Claude Code，贴一段代码问“这个项目是做什么的”。Claude Code 当然能回答，但回答得浅。然后他们拿着这个浅层的认知，直接让 Claude Code 开始改代码。改完后跑不通，或者跑通了但没达到预期，或者看起来达到了但上线就炸了。然后他们回过头来怪 Claude Code：“这玩意真没法用。”</p><p><strong>但问题不在 Claude Code，问题在于没有前六步打底，AI 就是瞎的</strong>。它不知道这个项目有什么坑、哪段代码动不得、哪些历史约定存在。这些东西你不告诉它，它就永远看不见。</p><p>反过来，如果你扎扎实实把前六步做完，把了解到的东西整理成文档，然后把这些文档交给 Claude Code，它的表现会完全不同。它会基于你提供的上下文做判断，它给的方案会贴合这个项目的实际情况，它改的代码会知道哪些地方要绕开。</p><p>这就是为什么这一讲我要花大篇幅讲“人原本是怎么做的”。 <strong>因为 AI 时代，这些步骤一步不能少，只是每一步人和 AI 的分工变了</strong>。</p><p>具体怎么变，下一讲我们展开。</p><h2 id="冷启动慢-飞轮转起来就快" tabindex="-1">冷启动慢，飞轮转起来就快 <a class="header-anchor" href="#冷启动慢-飞轮转起来就快" aria-label="Permalink to &quot;冷启动慢，飞轮转起来就快&quot;">​</a></h2><p>这一讲的最后，我想再说一件事，算是给你一个心理预期。</p><p>开篇词里我说过，改造一个跑了几年的老项目，像推动一辆满载的大卡车。 <strong>冷启动永远慢。</strong> 这一讲讲的九步链路，就是冷启动那一段。你要先找人聊、翻资料、读代码、搭环境、跑起来、摸接口、画链路。这一通操作下来可能要一两天甚至一两周。这段时间你感觉什么都没产出，心里容易焦虑。</p><p><strong>这种焦虑很正常，但你要知道，这不是浪费时间，是投资</strong>。做完冷启动之后，你会进入一个飞轮。</p><p>你对项目的理解越深，后续的改造越轻松。你积累的文档越厚，下次打开代码时的心智成本越低。你和 AI 协作时提供的上下文越准，AI 给的方案越贴合。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/974062/f5747a14448a8ca9e838e86a50c2d454.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/974062/f5747a14448a8ca9e838e86a50c2d454.png" alt=""></a></p><p>第一个改造任务可能要磨两三天，第二个可能一天，第三个几小时就搞定。老项目改造的核心心法就一句话： <strong>熬过冷启动</strong>。熬过去了，后面全是复利。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一讲我讲了一件事： <strong>老项目改造的真实链路</strong>。九个步骤，从了解到改造，从头到尾。AI 没有推翻这条链路，只是改变了每一步里人和 AI 的分工。</p><p>记住那个比例： <strong>70% 的时间花在了解上，30% 的时间才是动手</strong>。这个比例和直觉相反，但它决定了你和 AI 协作能不能稳。</p><p>记住那个心态： <strong>熬过冷启动</strong>。老项目改造不存在一口吃成胖子，但只要熬过起步阶段，后面越来越轻松。</p><p>这一讲还没讲到 Claude Code 具体怎么用。我希望你先理解那条人的原始链路，后面讲 AI 怎么进来、哪一步帮你做 80%、哪一步帮你做 30%、哪一步几乎插不上手，你才能对上焦。在你那个跑了三五年的老系统上，一步一步把自己的节奏跑出来。这个节奏建立起来之后，那个老项目就不再是负担，它会变成你最熟悉的工作对象。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>回想你上一次接手一个老项目，大致是怎么做的？和我讲的九步相比，你跳过了哪几步？跳过的那几步，事后给你带来了什么问题？</p></li><li><p>你现在手里正在维护或改造的那个项目，如果让你把“代码之外的那些东西”（隐性约定、历史原因、对接方细节）写下来，你能写多少？这些东西有没有写进项目的文档？如果没有，它们目前存在哪儿？</p></li></ol><p>欢迎在评论区把你的答案写出来。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>',71)])])}const A=t(r,[["render",p]]);export{h as __pageData,A as default};
